using System;using System.IO;using System.Linq;using System.Collections.Generic;using V15Voice;
public static class CreatorTests {
 static int count;static void Check(bool x,string n){if(!x)throw new Exception(n);Console.WriteLine("PASS "+n);count++;}static void Throws(Action a,string n){try{a();}catch(Exception){Check(true,n);return;}throw new Exception("Expected failure: "+n);}
 sealed class Engine:KokoroEngine {public int Calls,CancelAt;public bool BadModel;public override void CheckFiles(){if(BadModel)throw new Exception("missing real model fixture");}public override Wave Generate(string text,double speed,string output){Calls++;if(Calls==CancelAt){Cancelled=true;throw new OperationCanceledException();}double seconds=text.Contains("LONG")?5.6:text.Contains("SHORT")?2.8:4.04;int frames=(int)(seconds*24000);return new Wave{Rate=24000,Samples=Enumerable.Range(0,frames).Select(i=>i<frames-1200?(short)(5000*Math.Cos(i*(text.Contains("SHORT")?.05:.063))):(short)0).ToArray()};}}
 static RenderOptions O(string source,List<Cue> cues){return new RenderOptions{BaseSpeed=1,MinSpeed=.9,MaxSpeed=1.1,GentleFit=true,Breathing=BreathMode.None,NormalizeLoudness=false,ReportContext=new VoiceReportContext{SourcePath=source,SourceCues=cues,VoiceKey="K:3",Purpose="Creator fixture"}};}
 static List<Cue> Cues(){return new List<Cue>{new Cue{Id=1,Start=0,End=4,Text="LONG first sentence.",AnchorAfter=true},new Cue{Id=2,Start=4,End=8,Text="SHORT second sentence.",AnchorAfter=true},new Cue{Id=3,Start=8,End=12,Text="Third good sentence.",AnchorAfter=true}};}
 [STAThread]public static void Main(){string dir=Path.Combine(Path.GetTempPath(),"V15 creator kiểm tra "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);var cues=Cues();string source=Path.Combine(dir,"story.srt");File.WriteAllText(source,Scripts.ToSrt(cues));string original=StateFiles.Hash(source);var p=CreatorProject.Open(source,cues,dir);p.Voice="Fixture voice";var e=new Engine{Root=dir};var o=O(source,cues);
  Throws(()=>CreatorRenderer.Run(p,e,o,false,(n,m)=>{}),"Overflow prevents publication but keeps all stage results");Check(e.Calls==3&&p.Stages.All(s=>File.Exists(s.Audio)),"All three stages measured including after overflow");Check(!p.Stages[0].Success&&p.Stages[1].Success&&p.Stages[1].NeedsReview&&p.Output=="","Short stage pause is reviewable; overflow blocks final WAV");Check(File.ReadAllText(p.Report).Contains("THẤT BẠI")&&File.ReadAllText(p.Report).Contains("LONG"),"Failure report includes original narration and stage measurements");string goodHash=StateFiles.Hash(p.Stages[2].Audio),shortHash=StateFiles.Hash(p.Stages[1].Audio);p.Stages[1].Reviewed=true;p.Save();p=CreatorProject.Open(source,cues,dir);Check(p.Stages[1].Reviewed&&p.Stages[0].Natural>5,"Measurements, review and failed candidate persist across reopen");
  var bad=p.Stages[0];string a=bad.Audio;CreatorRenderer.Trial(p,bad,e,O(source,cues),"LONG still overflowing.");Check(File.ReadAllText(p.Report).Contains("CHƯA KHỚP KHUNG")&&bad.Audio==a,"Failed trial has an explicit mismatch report and retains A");CreatorRenderer.Trial(p,bad,e,O(source,cues),"New first sentence.");Check(File.Exists(bad.TrialAudio)&&bad.Audio==a&&bad.Text.Contains("LONG"),"Trial B is separate and does not silently replace A");Check(bad.TrialInfo.Contains("Vừa khung")&&File.ReadAllText(p.Report).Contains("ĐO THỬ"),"Trial has measured diagnostics and its own report");bad.Draft="New first sentence.";p.Accept(bad);Check(bad.Pending&&bad.PreviousAudio==a&&p.Output=="","Accepting revision queues just the changed stage");int before=e.Calls;string output=CreatorRenderer.Run(p,e,O(source,cues),true,(n,m)=>{});Check(e.Calls==before&&File.Exists(output),"Repair adopts the measured B candidate without repeating TTS");Check(p.Stages[0].Audio==bad.TrialAudio&&StateFiles.Hash(p.Stages[0].Audio)==bad.TrialHash,"Published stage uses exactly the B audio that was auditioned");Check(StateFiles.Hash(p.Stages[2].Audio)==goodHash&&StateFiles.Hash(p.Stages[1].Audio)==shortHash,"Unaffected stage audio is byte-for-byte preserved");Check(p.Stages[1].Reviewed,"Review survives reuse of unchanged stage");Check(FinalAudio.PcmFrames(output)==288000,"Merged WAV exactly matches twelve-second source");var merged=Wave.Read(output);Check(merged.Samples.Skip(8*24000).SequenceEqual(Wave.Read(p.Stages[2].Audio).Samples),"Untouched stage appears unchanged in unnormalized final WAV");Check(StateFiles.Hash(source)==original,"Repairs never overwrite original SRT");Check(File.ReadAllText(p.Report).Contains("Lời dùng: New first sentence.")&&File.ReadAllText(p.Report).Contains("Lời gốc: LONG"),"Repair report preserves old and new words explicitly");
  string priorA=p.Stages[0].Audio;CreatorRenderer.Trial(p,p.Stages[0],e,O(source,cues),p.Stages[0].Text);Check(p.Stages[0].Audio==priorA&&p.Stages[0].TrialAudio!=priorA,"Trial with identical words cannot overwrite A");p.Stages[0].Draft=p.Stages[0].Text;p.Accept(p.Stages[0]);Check(p.Stages[0].Pending,"A new take with unchanged words can be selected for repair");before=e.Calls;string another=CreatorRenderer.Run(p,e,O(source,cues),true,(n,m)=>{});Check(before==e.Calls&&another!=output&&File.Exists(output),"Reassembly reuses all stage audio and preserves prior WAV");var changed=O(source,cues);changed.BaseSpeed=1.05;Throws(()=>CreatorRenderer.Run(p,e,changed,true,(n,m)=>{}),"Repair-only refuses different voice or fitting signature");Check(p.Output=="","Failed new attempt cannot masquerade as a new WAV");
  var temp=CreatorProject.Open(source,cues,dir);before=e.Calls;File.WriteAllText(temp.Stages[2].Audio,"corrupt WAV");CreatorRenderer.Run(temp,e,O(source,cues),false,(n,m)=>{});Check(e.Calls==before+1,"A corrupt cached stage is regenerated without rerendering others");e.BadModel=true;Throws(()=>CreatorRenderer.Run(temp,e,O(source,cues),false,(n,m)=>{}),"Model preflight error still produces a failure report");Check(File.ReadAllText(temp.Report).Contains("missing real model"),"Original preflight error is retained");e.BadModel=false;
  File.AppendAllText(source,"\n");Throws(()=>CreatorRenderer.Run(p,e,O(source,cues),true,(n,m)=>{}),"Changed source rejected before applying old stage edits");var reset=CreatorProject.Open(source,cues,dir);Check(reset.Stages.All(s=>s.Accepted==""&&s.Key==""),"Changed source never inherits stale edits or measurements");
  string other=Path.Combine(dir,"cancel.srt");File.WriteAllText(other,Scripts.ToSrt(cues));var cancel=CreatorProject.Open(other,cues,dir);var ec=new Engine{Root=dir,CancelAt=2};Throws(()=>CreatorRenderer.Run(cancel,ec,O(other,cues),false,(n,m)=>{}),"Cancellation exits without final WAV");Check(File.Exists(cancel.Stages[0].Audio)&&File.ReadAllText(cancel.Report).Contains("ĐÃ DỪNG"),"Cancellation preserves completed stage and report");
  string va=Path.Combine(dir,"story.mp4"),nested=Path.Combine(dir,"other");Directory.CreateDirectory(nested);string vb=Path.Combine(nested,"story.mp4");File.WriteAllText(va,"");File.WriteAllText(vb,"");Check(CreatorProject.Pair(source,new[]{va,vb})==va,"Pairing prefers unique same-folder stem match");Check(CreatorProject.Pair(Path.Combine(dir,"third","story.srt"),new[]{va,vb})=="","Ambiguous stem pairing requires a manual choice");Check(CreatorProject.Pair(source,new[]{Path.Combine(dir,"missing.mp4")})=="","Missing videos are not falsely paired");
  Player video=new Player{DurationValue=90},audio=new Player{DurationValue=8.73};var transport=new ReviewTransport(video,audio){NewVoice=true,Loop=true};transport.Load(va,p.Stages[0].Audio,24,32,8.73);transport.Play();transport.Tick();Check(video.Position==24&&audio.Position==0&&video.Mute&&!audio.Mute,"Playback starts source video and new voice at corresponding positions");video.Position=26.4;audio.Position=.1;transport.Tick();Check(Math.Abs(audio.Position-2.4)<.0001,"Transport corrects an audio/video drift");video.Position=32.74;transport.Tick();Check(video.Position==24&&audio.Position==0,"Loop includes overflow candidate then returns both tracks to stage start");transport.Pause();double paused=video.Position;transport.Play();transport.Tick();Check(video.Position==paused,"Pause/resume keeps current position");transport.Pause();Check(!transport.Playing&&!video.Playing&&!audio.Playing,"Pause stops both streams");Console.WriteLine("TOTAL CREATOR "+count+" passed.");
 }
 sealed class Player:IReviewPlayer {public bool Ready{get{return true;}}public double Position{get;set;}public double DurationValue;public double Duration{get{return DurationValue;}}public bool Mute,Playing;public bool Muted{set{Mute=value;}}public int Volume{set{}}public void Load(string f){Position=0;}public void Play(){Playing=true;}public void Pause(){Playing=false;}}
}
